using System.Globalization;
using System.Text;
using XylemUI.Theme.Fluent;

namespace XylemUI.Tools.FluentTokens;

/// <summary>
/// Writes <c>FluentTokens.g.cs</c>: a record for each group of tokens with one property for each token, named as the token in
/// PascalCase, and the tables that fill them (design §13.2, "トークンの元").
/// </summary>
internal static class Generator
{
    private static readonly string[] Variants = ["Light", "Dark", "HighContrast"];

    /// <summary>
    /// Writes the generated file.
    /// </summary>
    /// <param name="directory">The folder of the token files (vendor/out/fluent/tokens).</param>
    /// <param name="output">The file to write.</param>
    public static void Write(string directory, string output)
    {
        TokenSources tokens = TokenSources.Read(directory);
        string commit = Commit(directory);
        var code = new StringBuilder();
        _ = code.Append(
            $$"""
            // <auto-generated>
            // Generated by tools/FluentTokensTool from packages/tokens/src of microsoft/fluentui (MIT, LICENSE-FluentUI.txt) at commit
            // {{commit}} (vendor/versions.lock). Do not edit: run `FluentTokensTool generate` again.
            // </auto-generated>
            #nullable enable

            using System.Numerics;
            using XylemUI.Text;

            namespace XylemUI.Theme.Fluent;

            """
        );
        WriteColors(code, tokens);
        WritePixels(code, "FluentSpacing", "The spacing tokens (global/spacings.ts), in logical pixels.", tokens.Spacing);
        WritePixels(code, "FluentSizes", "The stroke widths (global/strokeWidths.ts), in logical pixels.", tokens.StrokeWidths);
        WritePixels(code, "FluentRadii", "The corner radii (global/borderRadius.ts), in logical pixels.", tokens.Radii);
        WriteTypography(code, tokens);
        WriteShadows(code, tokens);
        WriteBrand(code, tokens);
        File.WriteAllText(output, code.ToString().ReplaceLineEndings("\n"), new UTF8Encoding(false));
    }

    private static string Pascal(string name) => char.ToUpperInvariant(name[0]) + name[1..];

    // A float literal: "12f", "0.5f".
    private static string Number(float value) => value.ToString("R", CultureInfo.InvariantCulture) + "f";

    private static string Expression(ColorSource source) =>
        source switch
        {
            FixedColor color => string.Create(CultureInfo.InvariantCulture, $"new(0x{color.R:X2}, 0x{color.G:X2}, 0x{color.B:X2}, 0x{color.A:X2})"),
            BrandStep step => string.Create(CultureInfo.InvariantCulture, $"brand[{step.Index}]"),
            SystemColor system => $"os.{system.Member}",
            _ => throw new InvalidOperationException($"{source} is not a color source."),
        };

    private static void WriteColors(StringBuilder code, TokenSources tokens)
    {
        _ = code.Append(
            """

            /// <summary>
            /// The colors of a <see cref="FluentTheme"/>: Fluent's alias colors (ColorTokens), its status palette (the status colors of
            /// ColorPaletteTokens), and its status colors (ColorStatusTokens), one property for each token.
            /// </summary>
            public sealed record FluentColors
            {

            """
        );
        foreach (string name in tokens.ColorNames)
        {
            _ = code.Append($"    /// <summary>Gets <c>{name}</c>.</summary>\n    public required Color {Pascal(name)} {{ get; init; }}\n\n");
        }

        foreach (string variant in Variants)
        {
            bool system = variant == "HighContrast";
            string file = variant switch
            {
                "Light" => "alias/lightColor.ts and alias/lightColorPalette.ts",
                "Dark" => "alias/darkColor.ts and alias/darkColorPalette.ts",
                _ => "alias/highContrastColor.ts and alias/highContrastColorPalette.ts",
            };
            _ = code.Append($"    /// <summary>\n    /// Returns the colors of {file}.\n    /// </summary>\n");
            _ = system
                ? code.Append("    /// <param name=\"os\">The OS's high-contrast colors, in place of Fluent's.</param>\n")
                : code.Append("    /// <param name=\"brand\">The 16 brand steps, step 10 first.</param>\n");
            _ = code.Append("    /// <returns>The colors.</returns>\n");
            _ = system
                ? code.Append($"    internal static FluentColors {variant}(HighContrastColors os) =>\n        new()\n        {{\n")
                : code.Append($"    internal static FluentColors {variant}(ReadOnlySpan<Color> brand) =>\n        new()\n        {{\n");
            IReadOnlyDictionary<string, ColorSource> colors = tokens.Colors[variant];
            foreach (string name in tokens.ColorNames)
            {
                ColorSource source = colors[name];
                _ = code.Append($"            {Pascal(name)} = {Expression(source)}, // {source.Origin}\n");
            }

            _ = code.Append("        };\n\n");
        }

        TrimBlankLine(code);
        _ = code.Append("}\n");
    }

    private static void WritePixels(StringBuilder code, string type, string summary, IReadOnlyList<PixelToken> tokens)
    {
        _ = code.Append($"\n/// <summary>\n/// {summary}\n/// </summary>\npublic sealed record {type}\n{{\n");
        foreach (PixelToken token in tokens)
        {
            _ = code.Append(
                $"    /// <summary>Gets <c>{token.Name}</c>.</summary>\n    public required float {Pascal(token.Name)} {{ get; init; }}\n\n"
            );
        }

        _ = code.Append("    /// <summary>\n    /// Gets Fluent's values.\n    /// </summary>\n");
        _ = code.Append($"    internal static {type} Standard {{ get; }} =\n        new()\n        {{\n");
        foreach (PixelToken token in tokens)
        {
            _ = code.Append($"            {Pascal(token.Name)} = {Number(token.Value)},\n");
        }

        _ = code.Append("        };\n}\n");
    }

    private static void WriteTypography(StringBuilder code, TokenSources tokens)
    {
        _ = code.Append(
            "\n/// <summary>\n/// The text styles (global/typographyStyles.ts): the sizes, line heights, and weights of global/fonts.ts.\n/// </summary>\npublic sealed record FluentTypography\n{\n"
        );
        foreach (TextStyleToken style in tokens.TextStyles)
        {
            _ = code.Append(
                $"    /// <summary>Gets <c>{style.Name}</c>.</summary>\n    public required FluentTextStyle {Pascal(style.Name)} {{ get; init; }}\n\n"
            );
        }

        _ = code.Append("    /// <summary>\n    /// Gets Fluent's values.\n    /// </summary>\n");
        _ = code.Append("    internal static FluentTypography Standard { get; } =\n        new()\n        {\n");
        foreach (TextStyleToken style in tokens.TextStyles)
        {
            _ = code.Append(
                string.Create(
                    CultureInfo.InvariantCulture,
                    $"            {Pascal(style.Name)} = new({Number(style.FontSize)}, {Number(style.LineHeight)}, new FontWeight({style.Weight})),\n"
                )
            );
        }

        _ = code.Append("        };\n}\n");
    }

    private static void WriteShadows(StringBuilder code, TokenSources tokens)
    {
        _ = code.Append(
            "\n/// <summary>\n/// The elevation shadows (utils/shadows.ts), each in the neutral colors and, with the suffix Brand, in the brand colors.\n/// </summary>\npublic sealed record FluentShadows\n{\n"
        );
        foreach (string suffix in new[] { string.Empty, "Brand" })
        {
            foreach (ShadowToken shadow in tokens.Shadows)
            {
                string name = shadow.Name + suffix;
                _ = code.Append(
                    $"    /// <summary>Gets <c>{name}</c>.</summary>\n    public required FluentShadow {Pascal(name)} {{ get; init; }}\n\n"
                );
            }
        }

        _ = code.Append(
            """
                /// <summary>
                /// Returns the shadows in the shadow colors of a theme (createShadowTokens).
                /// </summary>
                /// <param name="ambient">The color of the neutral ambient layer (colorNeutralShadowAmbient).</param>
                /// <param name="key">The color of the neutral key layer (colorNeutralShadowKey).</param>
                /// <param name="brandAmbient">The color of the brand ambient layer (colorBrandShadowAmbient).</param>
                /// <param name="brandKey">The color of the brand key layer (colorBrandShadowKey).</param>
                /// <returns>The shadows.</returns>
                internal static FluentShadows Create(Color ambient, Color key, Color brandAmbient, Color brandKey) =>
                    new()
                    {

            """
        );
        foreach (string suffix in new[] { string.Empty, "Brand" })
        {
            string ambient = suffix.Length == 0 ? "ambient" : "brandAmbient";
            string key = suffix.Length == 0 ? "key" : "brandKey";
            foreach (ShadowToken shadow in tokens.Shadows)
            {
                _ = code.Append($"            {Pascal(shadow.Name + suffix)} = new({Layer(shadow.Ambient, ambient)}, {Layer(shadow.Key, key)}),\n");
            }
        }

        _ = code.Append("        };\n}\n");
    }

    private static string Layer(ShadowLayer layer, string color) =>
        $"new BoxShadow({color}, new Vector2({Number(layer.X)}, {Number(layer.Y)}), {Number(layer.Blur)})";

    private static void WriteBrand(StringBuilder code, TokenSources tokens)
    {
        _ = code.Append(
            """

            /// <summary>
            /// Fluent's brand steps (global/brandColors.ts) and the lightness each step's color is made at from an accent color (design
            /// §13.2, "ブランドの 16 段の作り方", step 4).
            /// </summary>
            internal static class FluentBrand
            {
                /// <summary>
                /// Gets the 16 steps of <c>brandWeb</c>, step 10 first, as <c>0xRRGGBB</c>.
                /// </summary>
                public static ReadOnlySpan<uint> Web =>
                    [

            """
        );
        foreach (uint step in tokens.BrandWeb)
        {
            _ = code.Append(string.Create(CultureInfo.InvariantCulture, $"        0x{step:X6},\n"));
        }

        _ = code.Append(
            """
                ];

                /// <summary>
                /// Gets the L* (CIE Lab, D50) of each step of <see cref="Web"/>, step 10 first, through the conversion of
                /// <see cref="CieLab"/>.
                /// </summary>
                public static ReadOnlySpan<double> Lightness =>
                    [

            """
        );
        foreach (uint step in tokens.BrandWeb)
        {
            Lab lab = CieLab.FromSrgb(((step >> 16) & 0xFF) / 255.0, ((step >> 8) & 0xFF) / 255.0, (step & 0xFF) / 255.0);
            _ = code.Append($"        {lab.L.ToString("R", CultureInfo.InvariantCulture)},\n");
        }

        _ = code.Append("    ];\n}\n");
    }

    private static void TrimBlankLine(StringBuilder code)
    {
        if (code.Length >= 2 && code[^1] == '\n' && code[^2] == '\n')
        {
            code.Length--;
        }
    }

    // The commit of the token files, read from the line of vendor/versions.lock that pins global/colors.ts, three folders above
    // vendor/out/fluent/tokens: the heading of the generated file names the commit it was made from.
    private static string Commit(string directory)
    {
        string lockFile = Path.Combine(directory, "..", "..", "..", "versions.lock");
        foreach (string line in File.ReadLines(lockFile))
        {
            string[] fields = line.Split(' ', StringSplitOptions.RemoveEmptyEntries);
            if (fields.Length >= 2 && fields[0] == "fluent-tokens-global-colors")
            {
                return fields[1];
            }
        }

        throw new InvalidDataException($"{lockFile} has no line for fluent-tokens-global-colors.");
    }
}
